-- survives CMS renaming the file each revision), plus in-app training on the compliance model.

ALTER TABLE cms_sync_log ADD COLUMN IF NOT EXISTS run_by VARCHAR(160) NULL AFTER trigger_by;

-- Pre-configure the landscape connection so "Sync now" works out of the box.
INSERT INTO cms_sync_source (id, data_type, plan_year, state, url, label, active, sync_mode, created_at)
SELECT UUID(), 'landscape', 2026, 'FL',
       'https://www.cms.gov/medicare/coverage/prescription-drug-coverage',
