WHERE NOT EXISTS (SELECT 1 FROM cms_sync_source WHERE data_type='landscape' AND plan_year=2026);

-- Training: the compliance model + how to monitor it (visible in the Training Center).
INSERT IGNORE INTO training_library (code, title, category, authority, summary, body, link, link_label, minutes, sort, updated_at) VALUES
('flx-compliance-model', 'How compliance works: Requirements vs Credentials', 'Using FlxCoreHC', 'FlxCoreHC',
 'The three-piece model behind every compliance screen: the catalog defines WHAT exists, requirements define WHAT EACH PRODUCER MUST MAINTAIN, and credentials are the PROOF they actually hold.',
 'FlxCoreHC separates compliance into three pieces that work together.\n\n1) THE CATALOG (platform-wide). A master list of credential types that exist in the industry: the FL 2-15 license, AHIP certification, E&O insurance, carrier certifications, and so on. You never edit this per producer - it is the dictionary.\n\n2) REQUIREMENTS (per producer). From that catalog, each producer is assigned the set they MUST maintain - usually by applying a Compliance Template (e.g. "MA Producer - Florida") which ticks the right catalog items in one click. Requirements are the checklist. They say what must be true, but they are not documents.\n\n3) CREDENTIALS (per producer). These are the actual records the producer HOLDS: their real license with its number and expiry date, their AHIP certificate with this year''s completion, their E&O policy - each with evidence documents attached. Credentials are the proof.\n\nTHE ENGINE. FlxCoreHC continuously matches credentials against requirements. A requirement shows ACTIVE when a valid credential of that type is on file, EXPIRING when the matching credential is inside the warning window, EXPIRED when it lapsed, and MISSING when no credential covers it. Those statuses roll up into the 0-100 Compliance Score, drive automatic renewal tasks, and feed the Credential Package PDF you send carriers.\n\nSO THE DAILY WORKFLOW IS: assign requirements once (via a template), then keep credentials current. When something shows missing or expiring, you add or renew the CREDENTIAL - never the requirement. The requirement stays; the proof gets refreshed.',
 NULL, NULL, 6, 5, NOW()),
('flx-monitoring-compliance', 'Monitoring compliance: a manager''s routine', 'Using FlxCoreHC', 'FlxCoreHC',
 'Where to look each day, week, and season to keep the whole agency compliant: the Compliance overview, producer pages, tasks, reminders, and the AEP readiness view.',
 'DAILY (2 minutes). Open COMPLIANCE. The "Producers needing attention" panel ranks everyone below 100% coverage - each row shows the gap count. Click Open on the worst; the producer page shows exactly which requirements are missing or expired and which credential satisfies each one.\n\nWEEKLY (10 minutes). 1) Check "Expiring in 30 days" on the Compliance page and press "Send reminders now" so agents get email nudges. 2) Review open TASKS - renewal tasks are created automatically when credentials approach expiry, and they auto-close when the renewed credential is added. 3) Spot-check the audit trail (Organization > Audit) if you need to see who changed what, including NPI lookups and CMS plan syncs.\n\nPER PRODUCER. Each producer page reads top to bottom: their compliance template (the licence bundle governing them), their requirement checklist with live status chips, their credentials with evidence attached, and the one-click Credential Package PDF for carrier appointments. Managers and staff with the right role can edit the profile, add credentials, and upload documents on the producer''s behalf - producers can also self-serve through their portal.\n\nSEASONAL (Aug-Dec). The AEP readiness view tracks annual certifications (AHIP, carrier certs) for the coming plan year, and the platform plan catalog refreshes from the CMS landscape file so the book of business picks from official plan names.\n\nSCORE MEANING: 90-100 green (sellable), 60-89 amber (gaps to close), below 60 red (do not submit to carriers). The score only moves when credentials change - so fixing compliance always means adding or renewing a credential.',
 NULL, NULL, 7, 6, NOW());
